import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder.
    This operation is executed as a background process using the 'gzip' command.

    Parameters:
    - src_folder (str): The source folder containing files to compress.
    - dst_folder (str): The destination folder to move compressed files to.

    Returns:
    - dict: A dictionary containing:
        'success': A boolean indicating if all files were compressed and moved successfully.
        'message': A descriptive message about the operation's result.
        'failed_files': A list of filenames that failed to compress or move.
    """
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }

    if not os.path.isdir(dst_folder):
        try:
            os.makedirs(dst_folder)
        except OSError as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder '{dst_folder}': {e}",
                'failed_files': []
            }

    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    failed_files = []

    for file in files:
        src_path = os.path.join(src_folder, file)
        compressed_file = file + '.gz'
        dst_path = os.path.join(dst_folder, compressed_file)

        try:
            # Compress the file using gzip in the background
            process = subprocess.Popen(['gzip', '-c', src_path], stdout=open(dst_path, 'wb'))
            process.wait()

            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, 'gzip')

            # Remove the original file after successful compression and move
            os.remove(src_path)
        except Exception as e:
            failed_files.append(file)
            # Clean up partially created compressed file if it exists
            if os.path.exists(dst_path):
                os.remove(dst_path)

    if not failed_files:
        return {
            'success': True,
            'message': f"All files compressed and moved successfully from '{src_folder}' to '{dst_folder}'.",
            'failed_files': failed_files
        }
    else:
        return {
            'success': False,
            'message': f"Failed to compress and move some files from '{src_folder}' to '{dst_folder}'.",
            'failed_files': failed_files
        }
